function gdOverText(el){if(!el)return 0;var B=gdPR(el),a=0;ph.querySelectorAll("b,span,small,p,label,button,h1,h2,h3,h4,div,i,em,strong,a").forEach(function(x){if(x===el||el.contains(x)||x.contains(el)||x.children.length||!String(x.textContent).trim()||!gdSeen(x))return;
  var cs=getComputedStyle(x);if(cs.opacity==="0"||cs.visibility==="hidden")return;a+=gdOver(B,gdPR(x))});return Math.round(a)}
